window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7fae7adf3b3bc913"]={"versions": [{"id": "FIG-7fae7adf3b3bc913", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Blockschaltbild der AUTOSAR Classic Platform (Communication Stack). Das Diagramm illustriert das Konfigurationsbeispiel „Physical channel view definition example A“ für das CAN Interface (CanIf) mit einer 1:1-Zuordnung zwischen logischem CAN-Netzwerk und physikalischem Übertragungskanal („Use Case: 1:1 relation between CAN network and physical channel“). Es spannt den Bogen von den Service- und Management-Modulen (ComM, CanSM, CanNM) über die Abstraktionsschicht (CanIf) und die MCAL-/Treiber-Schicht (Can, CanTrcv) bis hinunter zur Controller- und Transceiver-Hardware sowie den physikalischen Busleitungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>COM Manager (ComM)</strong>: Zentrale Kommunikationsverwaltung, horizontal gekoppelt an die Instanzen <strong>CAN NM A</strong> und <strong>CAN NM B</strong> sowie vertikal zweikanalig an den CAN State Manager angebunden.\n</li><li><strong>CAN State Manager (CanSM)</strong>: Verwaltet den Netzwerk- und Kanalzustand beider CAN-Kanäle; bidirektional mit ComM und CanIf verbunden.\n</li><li><strong>CAN Interface (CanIf)</strong>: Zentrale Abstraktionsinstanz; bedient oberhalb den CanSM und unterhalb über standardisierte Treiberschnittstellen sowohl den CAN-Treiber als auch zwei Transceiver-Treiber.\n</li><li><strong>CAN driver</strong>: Einzelner MCAL-Treiber zur gleichzeitigen Ansteuerung zweier On-Chip-Controller gleichen Typs („Same types of CAN controllers“); bidirektional mit CanIf verbunden.\n</li><li><strong>CAN transceiver driver 0 &amp; CAN Transceiver Driver 1</strong>: Zwei separate Transceiver-Treiber zur Anbindung an CanIf, erforderlich aufgrund unterschiedlicher Transceiver-Hardware („Different types of CAN transceivers“; Hinweis: „Only one CAN transceiver driver is needed, of the transceiver type is same.“).\n</li><li><strong>CAN controller 0 &amp; CAN controller 1</strong>: Hardware-Controller, angesteuert durch den gemeinsamen CAN-Treiber und über Rx/Tx-Leitungen (Doppelstrich) mit den jeweiligen Transceivern gekoppelt.\n</li><li><strong>CAN transceiver 0 &amp; CAN transceiver 1</strong>: Physische Transceiver-Bausteine, gesteuert durch die jeweiligen Transceiver-Treiber und per Busleitungen (Doppelstrich) auf <strong>CAN network A</strong> bzw. <strong>CAN network B</strong> geführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Zustands- und Kontrollfluss</strong>: ComM initiiert kanalbezogene Zustandswechsel über den CanSM unter Koordination der Netzwerkmanagement-Instanzen CAN NM A bzw. CAN NM B. Der CanSM übersetzt diese Anforderungen in kanal- und controllerbezogene Steuerbefehle an das CanIf. CanIf delegiert die Steueraufrufe getrennt an den CAN-Treiber (Umschaltung von Controller 0 bzw. 1) sowie an den zuständigen Transceiver-Treiber (Treiber 0 für Transceiver 0, Treiber 1 für Transceiver 1 zur Modusumschaltung wie Normal, Standby oder Sleep).\n</li><li><strong>Datenfluss</strong>: Sende- und Empfangsdaten (PDUs) werden im CanIf kanalgranular geroutet. Das Senden erfolgt über den gemeinsamen CAN-Treiber an den adressierten Controller (0 oder 1) und wird über den zugehörigen Transceiver auf das physikalische Netz (A oder B) übertragen. Empfangene Daten und Bestätigungen gelangen über Controller-Interrupts/-Polling an den CAN-Treiber und weiter zur Auswertung ins CanIf.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Mehrkanaligkeit und Kanalunterscheidung (CANIF105)</strong>: CanIf muss mehrere physikalische CAN-Kanäle abstrahieren und für übergeordnete Module wie den CanSM unterscheidbar halten; im vorliegenden Use Case besteht eine feste 1:1-Relation zwischen Netzwerk und Hardwarepfad.\n</li><li><strong>Agnostizismus gegenüber Physical-Layer-Typen (CANIF169)</strong>: CanIf behandelt die Kanäle einheitlich und unabhängig davon, welche physikalische Schicht (z. B. High-Speed CAN oder Low-Speed CAN) zugrunde liegt.\n</li><li><strong>Treiberorganisation</strong>: Bei identischen CAN-Controllern genügt eine einzelne Multi-Channel-CAN-Treiberinstanz. Transceiver unterschiedlichen Typs verlangen hingegen zwingend separate Transceiver-Treiberinstanzen im ECU Abstraction Layer.\n</li></ul>"}, {"id": "FIG-8cdafde13e53c14b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Blockschaltbild der AUTOSAR Classic Platform (Communication Stack). Das Diagramm illustriert das Konfigurationsbeispiel „Physical channel view definition example A“ für das CAN Interface (CanIf) mit einer 1:1-Zuordnung zwischen logischem CAN-Netzwerk und physikalischem Übertragungskanal („Use Case: 1:1 relation between CAN network and physical channel“). Es spannt den Bogen von den Service- und Management-Modulen (ComM, CanSM, CanNM) über die Abstraktionsschicht (CanIf) und die MCAL-/Treiber-Schicht (Can, CanTrcv) bis hinunter zur Controller- und Transceiver-Hardware sowie den physikalischen Busleitungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>COM Manager (ComM)</strong>: Zentrale Kommunikationsverwaltung, horizontal gekoppelt an die Instanzen <strong>CAN NM A</strong> und <strong>CAN NM B</strong> sowie vertikal zweikanalig an den CAN State Manager angebunden.\n</li><li><strong>CAN State Manager (CanSM)</strong>: Verwaltet den Netzwerk- und Kanalzustand beider CAN-Kanäle; bidirektional mit ComM und CanIf verbunden.\n</li><li><strong>CAN Interface (CanIf)</strong>: Zentrale Abstraktionsinstanz; bedient oberhalb den CanSM und unterhalb über standardisierte Treiberschnittstellen sowohl den CAN-Treiber als auch zwei Transceiver-Treiber.\n</li><li><strong>CAN driver</strong>: Einzelner MCAL-Treiber zur gleichzeitigen Ansteuerung zweier On-Chip-Controller gleichen Typs („Same types of CAN controllers“); bidirektional mit CanIf verbunden.\n</li><li><strong>CAN transceiver driver 0 &amp; CAN Transceiver Driver 1</strong>: Zwei separate Transceiver-Treiber zur Anbindung an CanIf, erforderlich aufgrund unterschiedlicher Transceiver-Hardware („Different types of CAN transceivers“; Hinweis: „Only one CAN transceiver driver is needed, of the transceiver type is same.“).\n</li><li><strong>CAN controller 0 &amp; CAN controller 1</strong>: Hardware-Controller, angesteuert durch den gemeinsamen CAN-Treiber und über Rx/Tx-Leitungen (Doppelstrich) mit den jeweiligen Transceivern gekoppelt.\n</li><li><strong>CAN transceiver 0 &amp; CAN transceiver 1</strong>: Physische Transceiver-Bausteine, gesteuert durch die jeweiligen Transceiver-Treiber und per Busleitungen (Doppelstrich) auf <strong>CAN network A</strong> bzw. <strong>CAN network B</strong> geführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Zustands- und Kontrollfluss</strong>: ComM initiiert kanalbezogene Zustandswechsel über den CanSM unter Koordination der Netzwerkmanagement-Instanzen CAN NM A bzw. CAN NM B. Der CanSM übersetzt diese Anforderungen in kanal- und controllerbezogene Steuerbefehle an das CanIf. CanIf delegiert die Steueraufrufe getrennt an den CAN-Treiber (Umschaltung von Controller 0 bzw. 1) sowie an den zuständigen Transceiver-Treiber (Treiber 0 für Transceiver 0, Treiber 1 für Transceiver 1 zur Modusumschaltung wie Normal, Standby oder Sleep).\n</li><li><strong>Datenfluss</strong>: Sende- und Empfangsdaten (PDUs) werden im CanIf kanalgranular geroutet. Das Senden erfolgt über den gemeinsamen CAN-Treiber an den adressierten Controller (0 oder 1) und wird über den zugehörigen Transceiver auf das physikalische Netz (A oder B) übertragen. Empfangene Daten und Bestätigungen gelangen über Controller-Interrupts/-Polling an den CAN-Treiber und weiter zur Auswertung ins CanIf.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Mehrkanaligkeit und Kanalunterscheidung (CANIF105)</strong>: CanIf muss mehrere physikalische CAN-Kanäle abstrahieren und für übergeordnete Module wie den CanSM unterscheidbar halten; im vorliegenden Use Case besteht eine feste 1:1-Relation zwischen Netzwerk und Hardwarepfad.\n</li><li><strong>Agnostizismus gegenüber Physical-Layer-Typen (CANIF169)</strong>: CanIf behandelt die Kanäle einheitlich und unabhängig davon, welche physikalische Schicht (z. B. High-Speed CAN oder Low-Speed CAN) zugrunde liegt.\n</li><li><strong>Treiberorganisation</strong>: Bei identischen CAN-Controllern genügt eine einzelne Multi-Channel-CAN-Treiberinstanz. Transceiver unterschiedlichen Typs verlangen hingegen zwingend separate Transceiver-Treiberinstanzen im ECU Abstraction Layer.\n</li></ul>"}], "trans": [{"from": "FIG-7fae7adf3b3bc913", "to": "FIG-8cdafde13e53c14b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
